var calc_output = [];

var a = parseFloat(a);
var b = parseFloat(b);
var c = parseFloat(c);
var d = parseFloat(d);
var e = parseFloat(e);
var f = parseFloat(f);
var g = parseFloat(g);

// Calculate score
var score = a + b + c + d + e + f + g;

var mort = 100 / (1 + Math.exp(5.012 - score * 0.481));

// Output
calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: 'NHFS (30-day mortality: ' + mort.toFixed(1) + '%)'
});
